async def act(page):
    # Click the user menu button to open the dropdown
    await page.get_by_role("button", expanded=False).click()
    await page.wait_for_timeout(1000)  # Wait for dropdown to appear
    # Look for a link or button to set status in the dropdown
    try:
        await page.get_by_role("link", name="Set status", exact=True).click()
    except:
        try:
            await page.get_by_role("button", name="Set status", exact=True).click()
        except:
            # If not found, try other possible names
            try:
                await page.get_by_role("link", name="Edit status", exact=True).click()
            except:
                try:
                    await page.get_by_role("link", name="Status", exact=True).click()
                except:
                    # Fallback: click on the user profile link 'Byte Blaze' which might lead to settings
                    await page.get_by_role("link", name="Byte Blaze", exact=True).click()
                    await page.wait_for_load_state("networkidle")
                    # On profile page, look for status setting
                    try:
                        await page.get_by_role("button", name="Set status").click()
                    except:
                        print("Could not find status setting option.")
                        return
    # Wait for the status dialog to appear
    await page.wait_for_timeout(2000)
    # Fill the status textbox with 'Out of Office'
    try:
        await page.get_by_role("textbox", name="What's your status?").fill("Out of Office")
    except:
        try:
            await page.get_by_label("Status").fill("Out of Office")
        except:
            print("Status textbox not found.")
            return
    # Save or close the dialog
    try:
        await page.get_by_role("button", name="Close").click()
    except:
        try:
            await page.get_by_role("button", name="Save").click()
        except:
            # If no close or save button, assume auto-save
            pass
    await page.wait_for_timeout(1000)  # Wait for any UI updates

